// W1D2-BE: Prisma CLI settings (generated by `prisma init`, kept as TypeScript
// because that is Prisma's default). Tells Prisma where the schema and
// migrations live. Prisma 7 no longer reads .env by itself, so dotenv loads
// DATABASE_URL here. This file holds no secrets.
import "dotenv/config";
import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
